Page._content:
:root {
  --kaiyi-ink: #172033;
  --kaiyi-muted: #667085;
  --kaiyi-accent: #5267e8;
  --kaiyi-accent-soft: #eef0ff;
}

body {
  letter-spacing: 0.01em;
}

.navbar-brand {
  font-weight: 700;
  letter-spacing: -0.02em;
}

.banner .mask {
  background: linear-gradient(135deg, rgba(18, 25, 43, 0.88), rgba(52, 64, 145, 0.64));
}

.banner-text .h2,
.banner-text .h3 {
  letter-spacing: -0.03em;
}

.index-card {
  border: 1px solid rgba(17, 24, 39, 0.06);
  border-radius: 18px;
  box-shadow: 0 14px 40px rgba(25, 32, 56, 0.07);
}

.index-info .index-header {
  line-height: 1.35;
}

.markdown-body {
  color: var(--kaiyi-ink);
  font-size: 1.04rem;
  line-height: 1.95;
}

.markdown-body h2 {
  margin-top: 2.8em;
  letter-spacing: -0.02em;
}

.markdown-body blockquote {
  border-left-color: var(--kaiyi-accent);
  background: var(--kaiyi-accent-soft);
  border-radius: 0 10px 10px 0;
  color: #344054;
}

.markdown-body table {
  font-size: 0.95rem;
}

.career-timeline {
  margin: 1.5rem 0 2.5rem;
  padding-left: 1.6rem;
  border-left: 2px solid #e8eaf6;
}

.career-timeline h3 {
  position: relative;
  margin-top: 2rem;
}

.career-timeline h3::before {
  position: absolute;
  top: 0.45em;
  left: -2.02rem;
  width: 12px;
  height: 12px;
  border: 3px solid white;
  border-radius: 50%;
  background: var(--kaiyi-accent);
  box-shadow: 0 0 0 2px var(--kaiyi-accent);
  content: "";
}

@media (max-width: 767px) {
  .markdown-body {
    font-size: 1rem;
    line-height: 1.85;
  }

  .index-card {
    border-radius: 14px;
  }
}

